package com.dreamcore.workspace.evaluation;
import com.dreamcore.workspace.identity.*;
import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.json.JsonMapper;

@Service
public class EvaluationIssueService {
 public record Create(UUID sampleVersion,UUID evaluationId,String title,String category,String impact,String nextAction) {}
 public record Change(String status,UUID assignee,String outcome,String basis,String note,List<EvaluationAccess.Evidence> evidence) {}
 public record Event(int revision,String status,UUID assignee,String outcome,String basis,String note,List<EvaluationAccess.Evidence> evidence,UUID actor,Instant createdAt) {}
 public record Issue(UUID id,UUID tenantId,UUID workspaceId,UUID sampleVersion,UUID evaluationId,String title,String category,String impact,String nextAction,int revision,String status,UUID assignee,String outcome,List<Event> history) {}
 public record Page(List<Issue> items,boolean hasMore,int nextOffset) {}
 public record Assignee(UUID id,String name) {}
 private final JdbcTemplate db;private final EvaluationAccess access;private final EvaluationService evaluations;private final IdentityService identities;private final IdentityAudit audit;private final JsonMapper json=new JsonMapper();
 public EvaluationIssueService(JdbcTemplate db,EvaluationAccess access,EvaluationService evaluations,IdentityService identities,IdentityAudit audit){this.db=db;this.access=access;this.evaluations=evaluations;this.identities=identities;this.audit=audit;}
 private String hash(Object... x){return IdentityService.hash(json.writeValueAsString(x));}
 private Map<String,Object> row(UUID actor,UUID tenant,UUID id,boolean write,boolean lock){var rows=db.queryForList("SELECT * FROM evaluation_issues WHERE id=? AND NOT scrubbed AND (evaluation_id IS NULL OR object_is_active('EVALUATION_RUN',evaluation_id)) AND tenant_id IS NOT DISTINCT FROM ?::uuid"+(lock?" FOR UPDATE":""),id,tenant);if(rows.isEmpty())throw access.missing();var r=rows.getFirst();access.scope(actor,tenant,(UUID)r.get("workspace_id"),write);evaluations.byVersion(actor,tenant,(UUID)r.get("sample_version"));if(r.get("evaluation_id")!=null)evaluations.evaluation(actor,tenant,(UUID)r.get("evaluation_id"));return r;}
 @Transactional public Issue get(UUID actor,UUID tenant,UUID id){var r=row(actor,tenant,id,false,false);UUID workspace=(UUID)r.get("workspace_id");var history=db.query("SELECT * FROM evaluation_issue_events WHERE issue_id=? ORDER BY revision",(e,n)->new Event(e.getInt("revision"),e.getString("status"),e.getObject("assignee",UUID.class),e.getString("outcome"),e.getString("basis"),e.getString("note"),json.readValue(e.getString("evidence"),EvaluationService.EvidenceSet.class).items(),e.getObject("actor_id",UUID.class),e.getTimestamp("created_at").toInstant()),id);for(var h:history)for(var e:h.evidence())access.evidence(actor,tenant,workspace,e);return new Issue(id,tenant,workspace,(UUID)r.get("sample_version"),(UUID)r.get("evaluation_id"),(String)r.get("title"),(String)r.get("category"),(String)r.get("impact"),(String)r.get("next_action"),((Number)r.get("revision")).intValue(),(String)r.get("status"),(UUID)r.get("assignee"),(String)r.get("outcome"),history);}
 private void append(UUID actor,UUID id,int rev,Change c){db.update("INSERT INTO evaluation_issue_events(id,issue_id,revision,status,assignee,outcome,basis,note,evidence,actor_id) VALUES (?,?,?,?,?,?,?,?,?::jsonb,?)",UUID.randomUUID(),id,rev,c.status(),c.assignee(),c.outcome(),c.basis(),c.note(),json.writeValueAsString(new EvaluationService.EvidenceSet(c.evidence())),actor);}
 @Transactional public Issue create(UUID actor,UUID tenant,UUID workspace,UUID key,Create c){
  if(c==null||c.category()==null||!Set.of("DATA","CONTENT","PREFERENCE","TECHNICAL","AUTHORIZATION","METHOD").contains(c.category()))throw IdentityException.invalid();EvaluationService.text(c.title(),180,true);EvaluationService.text(c.impact(),2000,true);EvaluationService.text(c.nextAction(),1000,true);access.scope(actor,tenant,workspace,true);String h=hash(tenant,workspace,c);UUID prior=identities.priorRequest(actor,key,"EVAL_ISSUE_CREATE",h);access.scope(actor,tenant,workspace,true);if(prior!=null)return get(actor,tenant,prior);
  var sample=evaluations.byVersion(actor,tenant,c.sampleVersion());if(!sample.kind().equals("SAMPLE")||!Objects.equals(workspace,sample.workspaceId()))throw IdentityException.invalid();if(c.evaluationId()!=null){var run=evaluations.evaluation(actor,tenant,c.evaluationId());if(!run.sampleVersions().contains(c.sampleVersion()))throw IdentityException.invalid();}
  UUID id=UUID.randomUUID();db.update("INSERT INTO evaluation_issues(id,tenant_id,workspace_id,sample_version,evaluation_id,title,category,impact,next_action,created_by) VALUES (?,?,?,?,?,?,?,?,?,?)",id,tenant,workspace,c.sampleVersion(),c.evaluationId(),c.title(),c.category(),c.impact(),c.nextAction(),actor);append(actor,id,1,new Change("OPEN",null,null,null,"问题已登记；未更改原业务对象。",List.of()));identities.remember(actor,key,"EVAL_ISSUE_CREATE",h,id);audit.record(actor,tenant,"EVALUATION_ISSUE_CREATE",id,"SUCCESS");return get(actor,tenant,id);
 }
 @Transactional public Issue change(UUID actor,UUID tenant,UUID id,UUID key,int expected,Change c){
  if(c==null||c.status()==null||!Set.of("OPEN","IN_PROGRESS","WAITING","REVIEW","CLOSED").contains(c.status())||c.evidence()==null||c.evidence().size()>20)throw IdentityException.invalid();EvaluationService.text(c.note(),2000,true);var first=row(actor,tenant,id,true,false);String h=hash(tenant,id,expected,c);UUID prior=identities.priorRequest(actor,key,"EVAL_ISSUE_CHANGE",h);var r=row(actor,tenant,id,true,true);if(prior!=null)return get(actor,tenant,id);if(((Number)r.get("revision")).intValue()!=expected)throw new IdentityException(409,"EVALUATION_ISSUE_CHANGED");UUID workspace=(UUID)r.get("workspace_id");
  get(actor,tenant,id); // The actor must still see every previously attached result.
  if(c.assignee()!=null){access.scope(c.assignee(),tenant,workspace,true);get(c.assignee(),tenant,id);} // assignment does not grant access
  for(var e:c.evidence()){var f=access.evidence(actor,tenant,workspace,e);if(!f.exact())throw new IdentityException(409,"EVALUATION_EVIDENCE_CHANGED");if(c.assignee()!=null)access.evidence(c.assignee(),tenant,workspace,e);for(UUID source:f.sources())db.update("INSERT INTO evaluation_issue_sources(issue_id,material_version) VALUES (?,?) ON CONFLICT DO NOTHING",id,source);}
  if(c.status().equals("CLOSED")){
   if(c.outcome()==null||!Set.of("FIXED","DUPLICATE","NOT_REPRODUCIBLE","ACCEPTED_TRADEOFF","SUPERSEDED").contains(c.outcome())||!"HUMAN_CONFIRMATION".equals(c.basis()))throw IdentityException.invalid();
  }else if(c.outcome()!=null||c.basis()!=null)throw IdentityException.invalid();
  if(Set.of("IN_PROGRESS","REVIEW").contains(c.status())&&c.assignee()==null)throw new IdentityException(409,"ISSUE_ASSIGNEE_REQUIRED");
  if("CLOSED".equals(r.get("status"))&&!c.status().equals("OPEN"))throw new IdentityException(409,"ISSUE_REOPEN_REQUIRED");
  db.update("UPDATE evaluation_issues SET revision=revision+1,status=?,assignee=?,outcome=? WHERE id=?",c.status(),c.assignee(),c.outcome(),id);append(actor,id,expected+1,c);identities.remember(actor,key,"EVAL_ISSUE_CHANGE",h,id);audit.record(actor,tenant,"EVALUATION_ISSUE_CHANGE",id,"SUCCESS");return get(actor,tenant,id);
 }
 @Transactional public Page list(UUID actor,UUID tenant,UUID workspace,int offset,int limit){EvaluationService.bounds(offset,limit);access.scope(actor,tenant,workspace,false);var ids=db.queryForList("SELECT id FROM evaluation_issues WHERE tenant_id IS NOT DISTINCT FROM ?::uuid AND workspace_id IS NOT DISTINCT FROM ?::uuid ORDER BY created_at DESC,id LIMIT 1001",UUID.class,tenant,workspace);if(ids.size()>1000)throw new IdentityException(409,"EVALUATION_SCOPE_WINDOW_LIMIT");var out=new ArrayList<Issue>();for(UUID id:ids)try{out.add(get(actor,tenant,id));}catch(IdentityException ex){if(ex.status!=403&&ex.status!=404)throw ex;}return new Page(out.stream().skip(offset).limit(limit).toList(),out.size()>offset+limit,Math.min(out.size(),offset+limit));}
 @Transactional public List<Assignee> assignees(UUID actor,UUID tenant,UUID id){var r=row(actor,tenant,id,true,false);var candidates=tenant==null?db.queryForList("SELECT account_id FROM platform_roles WHERE role='PLATFORM_ADMIN' ORDER BY account_id LIMIT 101",UUID.class):db.queryForList("SELECT account_id FROM tenant_memberships WHERE tenant_id=? AND status='ACTIVE' ORDER BY account_id LIMIT 101",UUID.class,tenant);if(candidates.size()>100)throw new IdentityException(409,"ISSUE_ASSIGNEE_WINDOW_LIMIT");var out=new ArrayList<Assignee>();for(UUID a:candidates)try{access.scope(a,tenant,(UUID)r.get("workspace_id"),true);get(a,tenant,id);out.add(new Assignee(a,identities.account(a).displayName()));}catch(IdentityException ex){if(!Set.of(401,403,404).contains(ex.status))throw ex;}return List.copyOf(out);}
}
